// ══════════════════════════════════════════════════════════════════════════════
// openPrintWindow — renders print content in an overlay on the current window
// ══════════════════════════════════════════════════════════════════════════════
//
// WHY OVERLAY INSTEAD OF A POPUP WINDOW
//
// Three attempts at popup-based printing all hit the same wall:
//
//   Attempt 1  document.write on about:blank
//     Chrome treats dynamically written about:blank as a "null origin" in
//     certain contexts; inline onclick handlers and window.print() are silently
//     blocked — buttons render but do nothing.
//
//   Attempt 2  blob: URL popup
//     A blob: URL IS a real same-origin document so script runs fine, but
//     Chrome's focus-stealing prevention means window.open() typically opens
//     the popup *behind* the main window. The user cannot see it. Clicking
//     what looks like the Print button actually clicks the main app. The popup's
//     window.focus() call is blocked by the same policy, so the popup never
//     comes to the front.
//
//   Solution   full-screen overlay in the current window
//     • No popup → no popup blocker, no focus issues, no null-origin sandboxing.
//     • window.print() fires on the main window → always works from a click.
//     • @media print CSS hides everything except the overlay so the correct
//       content is printed; the overlay is then removed by afterprint or Close.
//
// Usage (same call sites as before — no module changes needed):
//   openPrintWindow(`<!DOCTYPE html><html>...${ printBootstrap() }...</html>`);
//
// ══════════════════════════════════════════════════════════════════════════════
export function openPrintWindow(html) {
  // ── Parse via DOMParser so the browser handles charset, entities and nested
  //    markup without the regex fragility of manual string manipulation.
  const withMeta = /<meta\s[^>]*charset/i.test(html)
    ? html
    : html.replace(/(<head[^>]*>)/i, '$1<meta charset="utf-8">');
  const parsed = new DOMParser().parseFromString(withMeta, 'text/html');

  // ── Collect all <style> blocks from the document — includes printBootstrap
  //    styles, PRINT_CSS, module-specific table/cell styles, @page declarations.
  const styles = [...parsed.querySelectorAll('style')]
    .map(s => s.textContent).join('\n');

  // ── Build an overlay that fills the viewport over the app.
  //    innerHTML is used deliberately: scripts injected via innerHTML are NOT
  //    executed by the browser, so the printBootstrap auto-print timer does not
  //    fire from here — we control the timing ourselves below.
  const overlay = document.createElement('div');
  overlay.id = '__slot_print';
  overlay.innerHTML = parsed.body.innerHTML;

  // ── Combined <style>:
  //    • all styles from the document (scoped naturally by the overlay's DOM),
  //    • on screen: overlay covers the viewport,
  //    • on paper: only the overlay prints; everything else is hidden.
  const styleEl = document.createElement('style');
  styleEl.id = '__slot_print_css';
  styleEl.textContent = `
${styles}
@media screen {
  #__slot_print {
    position: fixed; inset: 0; z-index: 2147483647;
    background: #fff; overflow: auto;
    font-family: 'Segoe UI', Arial, sans-serif;
  }
}
@media print {
  /* Force background colours (th, status badges, totals row) to print even
     when the user has "Background graphics" unchecked in Chrome's print UI. */
  * { -webkit-print-color-adjust: exact; print-color-adjust: exact; }
  body > *:not(#__slot_print) { display: none !important; }
  #__slot_print {
    position: static !important; display: block !important;
    padding: 0 !important; overflow: visible !important;
  }
}`;

  // ── Cleanup: remove the overlay and its styles.
  //    Called by: (a) afterprint event, (b) the Close button.
  function cleanup() {
    document.getElementById('__slot_print')?.remove();
    document.getElementById('__slot_print_css')?.remove();
    window.removeEventListener('afterprint', cleanup);
  }

  // ── Re-wire toolbar buttons. The inline onclick attributes parsed from the
  //    HTML string reference a popup's window.print() / window.close() — those
  //    are overridden here to target the correct main-window context.
  const goBtn    = overlay.querySelector('.print-toolbar .go');
  const closeBtn = overlay.querySelector('.print-toolbar .close');
  if (goBtn)    goBtn.onclick    = () => window.print();
  if (closeBtn) closeBtn.onclick = cleanup;

  window.addEventListener('afterprint', cleanup);

  // ── Mount, then trigger print after a short delay so images (SLOT logo
  //    especially) finish laying out — printing instantly yields a blank header.
  document.head.appendChild(styleEl);
  document.body.appendChild(overlay);
  setTimeout(() => window.print(), 300);
}

// ══════════════════════════════════════════════════════════════════════════════
// printBootstrap — make a generated print window actually print
// ══════════════════════════════════════════════════════════════════════════════
//
// THE BUG THIS REPLACES (found 2026-08-04, reported by the terminal team)
//
// Every print in this app was built the same way: open a blank window,
// document.write() the HTML, document.close(), and end the markup with
//
//     <script>window.onload=()=>window.print()<\/script>
//
// That handler frequently never fires. document.close() finishes the document
// immediately, so by the time the inline script runs the `load` event has
// often already been dispatched — assigning window.onload afterwards attaches
// a listener to an event that is never coming. The user gets a page with no
// print dialog and no button, which is exactly what was reported: "immediately
// I click print, it pops up this page which has nowhere to click print."
//
// It was in 34 places across 14 modules, so it was fixed here rather than
// once at the call site.
//
// THREE LAYERS, so a print always reaches the user:
//   1. a visible toolbar with Print and Close buttons — .no-print keeps it off
//      the paper. Even if every automatic trigger fails, there is a button.
//   2. plain timers — never requestAnimationFrame. rAF does not fire in a
//      window that is not being painted (a popup opening behind the main
//      window), which stalled the first version of this fix entirely. A short
//      delay still runs first so images — the SLOT logo especially — have laid
//      out; printing instantly yields a sheet with a blank header.
//   3. document.readyState is checked instead of trusting onload, and an
//      unconditional timer fires even if 'load' never arrives. Every trigger
//      calls doPrint() directly, and the "already printed" guard sits on that
//      function — so no trigger can consume the flag and leave the others dead.
//
// @param {object} opts
//   landscape — wide tables (10+ columns) are unreadable on portrait A4
// ══════════════════════════════════════════════════════════════════════════════
export function printBootstrap({ landscape = false } = {}) {
  return `
  <style>
    @page { size: A4 ${landscape ? 'landscape' : 'portrait'}; margin: 10mm; }
    .print-toolbar{position:fixed;top:0;left:0;right:0;z-index:9999;display:flex;gap:10px;
      align-items:center;justify-content:flex-end;padding:10px 16px;background:#0F3A1A;
      box-shadow:0 2px 8px rgba(0,0,0,.25);font-family:'Segoe UI',Arial,sans-serif}
    .print-toolbar span{margin-right:auto;color:rgba(255,255,255,.75);font-size:12px}
    .print-toolbar button{border:none;border-radius:6px;padding:7px 16px;font-size:13px;
      font-weight:600;cursor:pointer}
    .print-toolbar .go{background:#2FA84F;color:#fff}
    .print-toolbar .close{background:transparent;color:#fff;border:1px solid rgba(255,255,255,.4)}
    body{padding-top:56px !important}
    @media print{.print-toolbar{display:none !important}body{padding-top:0 !important}}
  </style>
  <div class="print-toolbar no-print">
    <span>Use your browser's print dialog to change paper size, orientation or save as PDF.</span>
    <button class="go" onclick="window.print()">🖨 Print</button>
    <button class="close" onclick="window.close()">Close</button>
  </div>
  <script>
    (function () {
      // 2026-08-04, second pass. The first version waited on
      // requestAnimationFrame before printing. rAF does not fire in a window
      // that is not being painted — a popup that opens behind the main
      // window, or on a minimised/background tab — so the chain stalled and
      // no dialog ever appeared. Worse, the 1.2s fallback called the same
      // entry point, which had already flipped its "started" flag and
      // returned immediately: the safety net was attached to the wrong end.
      //
      // Now the guard sits on the PRINT ITSELF, every trigger calls it
      // directly, and there is no rAF anywhere. A plain timer runs whether or
      // not the window is painted.
      var printed = false;
      function doPrint() {
        if (printed) return;
        printed = true;
        try { window.focus(); } catch (e) {}   // bring a background popup forward
        window.print();
      }
      // Small delay lets the logo and table lay out; printing instantly can
      // produce a sheet with a blank header.
      if (document.readyState === 'complete') setTimeout(doPrint, 300);
      else window.addEventListener('load', function () { setTimeout(doPrint, 300); });
      setTimeout(doPrint, 1500);   // fires even if 'load' never arrives
    })();
  <\/script>`;
}
